  version: string
  policy?: {
    state: string
    terms: string
  }
}

import consola from "consola"

import { updateCopilotPricing } from "~/lib/copilot-pricing"

const REFRESH_INTERVAL_MS = 30 * 60 * 1000

type PricingUpdater = () => Promise<{ status: string }>

let refreshPromise: Promise<void> | undefined
let refreshTimer: ReturnType<typeof setTimeout> | undefined
let pricingUpdater: PricingUpdater = updateCopilotPricing
let shuttingDown = false
let shutdownHandlersInstalled = false

async function refreshPricing(): Promise<void> {
  refreshPromise ??= pricingUpdater()
    .then((result) => {
      consola.debug(`Copilot pricing cache ${result.status}`)
    })
    .catch((error: unknown) => {
      consola.warn("Failed to refresh Copilot pricing cache:", error)
    })
    .finally(() => {
      refreshPromise = undefined
    })
  return refreshPromise
}

function scheduleNextRefresh(): void {
  if (shuttingDown) return
  refreshTimer = setTimeout(() => {
    void refreshPricing().finally(scheduleNextRefresh)
  }, REFRESH_INTERVAL_MS)
  refreshTimer.unref()
}

export async function startPricingScheduler(
  updater: PricingUpdater = updateCopilotPricing,
): Promise<void> {
  shuttingDown = false
  pricingUpdater = updater
  await refreshPricing()
  if (!refreshTimer) scheduleNextRefresh()

  if (!shutdownHandlersInstalled) {
    shutdownHandlersInstalled = true
    for (const signal of ["SIGINT", "SIGTERM"] as const) {
      process.once(signal, stopPricingScheduler)
    }
  }
}

export function stopPricingScheduler(): void {
  shuttingDown = true
  if (refreshTimer) clearTimeout(refreshTimer)
  refreshTimer = undefined
}

#!/usr/bin/env node

import { defineCommand } from "citty"
import clipboard from "clipboardy"
import consola from "consola"
import { serve, type ServerHandler } from "srvx"
import invariant from "tiny-invariant"

import { ensurePaths } from "./lib/paths"
import { initProxyFromEnv } from "./lib/proxy"
import { generateEnvScript } from "./lib/shell"
import { state } from "./lib/state"
import { setupCopilotToken, setupGitHubToken } from "./lib/token"
import { cacheModels, cacheVSCodeVersion } from "./lib/utils"
import { server } from "./server"
import { startPricingScheduler } from "./services/copilot/pricing-scheduler"

interface RunServerOptions {
  port: number
  verbose: boolean
  accountType: string
  manual: boolean
  rateLimit?: number
  rateLimitWait: boolean
  githubToken?: string
  claudeCode: boolean
  showToken: boolean
  proxyEnv: boolean
  hideInternal: boolean
  modelFilter?: string
}

export async function runServer(options: RunServerOptions): Promise<void> {
  if (options.proxyEnv) {
    initProxyFromEnv()
  }

  if (options.verbose) {
    consola.level = 5
    consola.info("Verbose logging enabled")
  }

  state.accountType = options.accountType
  if (options.accountType !== "individual") {
    consola.info(`Using ${options.accountType} plan GitHub account`)
  }

  state.manualApprove = options.manual
  state.rateLimitSeconds = options.rateLimit
  state.rateLimitWait = options.rateLimitWait
  state.showToken = options.showToken
  state.hideInternal = options.hideInternal
  state.modelFilter = options.modelFilter

  await ensurePaths()
  await cacheVSCodeVersion()

  if (options.githubToken) {
    state.githubToken = options.githubToken
    consola.info("Using provided GitHub token")
  } else {
    await setupGitHubToken()
  }

  await setupCopilotToken()
  await startPricingScheduler()
  await cacheModels()

  const modelCount = state.models?.data.length ?? 0
  consola.info(
    `Available models (${modelCount} loaded): \n${state.models?.data.map((model) => `- ${model.id}`).join("\n")}`,
  )

  const serverUrl = `http://localhost:${options.port}`

  // Detect 1M context from ANTHROPIC_MODEL env var (set before proxy starts)
  const anthropicModelEnv = process.env.ANTHROPIC_MODEL ?? ""
  const is1MFromEnv =
    anthropicModelEnv.includes("[1m]") || anthropicModelEnv.endsWith("-1m")
  if (is1MFromEnv) {
    state.is1MContext = true
    consola.info("1M context window mode enabled (from ANTHROPIC_MODEL)")
  }

  if (options.claudeCode) {
    invariant(state.models, "Models should be loaded by now")

    const selectedModel = await consola.prompt(
      "Select a model to use with Claude Code",
      {
        type: "select",
        options: state.models.data.map((model) => model.id),
      },
    )

    // Detect 1M context from interactive selection

    state.is1MContext = state.is1MContext || selectedModel.endsWith("-1m")
    if (selectedModel.endsWith("-1m")) {
      consola.info("1M context window mode enabled (from model selection)")
    }

    const selectedSmallModel = await consola.prompt(
      "Select a small model to use with Claude Code",
      {
        type: "select",
        options: state.models.data.map((model) => model.id),
      },
    )

    const command = generateEnvScript(
      {
        ANTHROPIC_BASE_URL: serverUrl,
        ANTHROPIC_AUTH_TOKEN: "dummy",
        ANTHROPIC_MODEL: selectedModel,
        ANTHROPIC_DEFAULT_SONNET_MODEL: selectedModel,
        ANTHROPIC_SMALL_FAST_MODEL: selectedSmallModel,
        ANTHROPIC_DEFAULT_HAIKU_MODEL: selectedSmallModel,
        DISABLE_NON_ESSENTIAL_MODEL_CALLS: "1",
        CLAUDE_CODE_DISABLE_NONESSENTIAL_TRAFFIC: "1",
      },
      "claude",
    )

    try {
      clipboard.writeSync(command)
      consola.success("Copied Claude Code command to clipboard!")
    } catch {
      consola.warn(
        "Failed to copy to clipboard. Here is the Claude Code command:",
      )
      consola.log(command)
    }
  }

  consola.box(
    `🌐 Usage Viewer: https://ericc-ch.github.io/copilot-api?endpoint=${serverUrl}/usage`,
  )

  serve({
    fetch: server.fetch as ServerHandler,
    port: options.port,
  })
}

export const start = defineCommand({
  meta: {
    name: "start",
    description: "Start the Copilot API server",
  },
  args: {
    port: {
      alias: "p",
      type: "string",
      default: "4141",
      description: "Port to listen on",
    },
    verbose: {
      alias: "v",
      type: "boolean",
      default: false,
      description: "Enable verbose logging",
    },
    "account-type": {
      alias: "a",
      type: "string",
      default: "individual",
      description: "Account type to use (individual, business, enterprise)",
    },
    manual: {
      type: "boolean",
      default: false,
      description: "Enable manual request approval",
    },
    "rate-limit": {
      alias: "r",
      type: "string",
      description: "Rate limit in seconds between requests",
    },
    wait: {
      alias: "w",
      type: "boolean",
      default: false,
      description:
        "Wait instead of error when rate limit is hit. Has no effect if rate limit is not set",
    },
    "github-token": {
      alias: "g",
      type: "string",
      description:
        "Provide GitHub token directly (must be generated using the `auth` subcommand)",
    },
    "claude-code": {
      alias: "c",
      type: "boolean",
      default: false,
      description:
        "Generate a command to launch Claude Code with Copilot API config",
    },
    "show-token": {
      type: "boolean",
      default: false,
      description: "Show GitHub and Copilot tokens on fetch and refresh",
    },
    "proxy-env": {
      type: "boolean",
      default: false,
      description: "Initialize proxy from environment variables",
    },
    "hide-internal": {
      type: "boolean",
      default: false,
      description:
        "Hide internal and account-scoped models from the /models response",
    },
    "model-filter": {
      type: "string",
      description:
        "Filter /models response to only show models from a specific vendor (e.g. anthropic, openai)",
    },
  },
  run({ args }) {
    const rateLimitRaw = args["rate-limit"]
    const rateLimit =
      // eslint-disable-next-line @typescript-eslint/no-unnecessary-condition
      rateLimitRaw === undefined ? undefined : Number.parseInt(rateLimitRaw, 10)

    return runServer({
      port: Number.parseInt(args.port, 10),
      verbose: args.verbose,
      accountType: args["account-type"],
      manual: args.manual,
      rateLimit,
      rateLimitWait: args.wait,
      githubToken: args["github-token"],
      claudeCode: args["claude-code"],
      showToken: args["show-token"],
      proxyEnv: args["proxy-env"],
      hideInternal: args["hide-internal"],
      modelFilter: args["model-filter"],
    })
  },
})

import { describe, expect, it } from "bun:test"

import { parseCopilotPricingYaml, pricingForModel } from "~/lib/copilot-pricing"

const FIXTURE = `
- model: GPT-5.6 Sol
  provider: openai
  category: Powerful
  threshold: '≤ 272K'
  tier: Default
  input: $5.00
  cached_input: $0.50
  output: $30.00
- model: GPT-5.6 Sol
  provider: openai
  category: Powerful
  threshold: '> 272K'
  tier: 'Long context'
  input: $10.00
  cached_input: $1.00
  output: $45.00
- model: Claude Haiku 4.5
  provider: anthropic
  category: Versatile
  input: $1.00
  cached_input: $0.10
  output: $5.00
  cache_write: $1.25
`

describe("Copilot pricing parser", () => {
  it("parses default and long-context GPT pricing", () => {
    const pricing = parseCopilotPricingYaml(FIXTURE, {
      etag: '"fixture"',
      fetchedAt: "2026-01-01T00:00:00.000Z",
    })
    const sol = pricingForModel(pricing, "gpt-5.6-sol")

    expect(sol?.category).toBe("powerful")
    expect(sol?.tiers).toHaveLength(2)
    expect(sol?.tiers[0]).toMatchObject({
      name: "default",
      input_threshold: { operator: "lte", tokens: 272_000 },
      credits_per_1m: {
        input: 500,
        cache_read: 50,
        cache_write: null,
        output: 3000,
      },
    })
    expect(sol?.tiers[1]).toMatchObject({
      name: "long-context",
      input_threshold: { operator: "gt", tokens: 272_000 },
      credits_per_1m: { input: 1000, output: 4500 },
    })
    expect(pricing.source.etag).toBe('"fixture"')
    expect(pricing.source.version).toStartWith("sha256:")
  })

  it("parses Anthropic cache-write pricing", () => {
    const pricing = parseCopilotPricingYaml(FIXTURE)
    expect(
      pricingForModel(pricing, "claude-haiku-4.5")?.tiers[0],
    ).toMatchObject({
      credits_per_1m: {
        input: 100,
        cache_read: 10,
        cache_write: 125,
        output: 500,
      },
    })
  })

  it("reports unmatched model names rather than guessing", () => {
    const pricing = parseCopilotPricingYaml(
      `${FIXTURE}\n- model: Future Model\n  input: $1\n  output: $2\n`,
    )
    expect(pricing.unmatched_models).toContain("Future Model")
  })

  it("rejects structurally empty sources", () => {
    expect(() => parseCopilotPricingYaml("[]")).toThrow(
      "Pricing source contains no model rows",
    )
  })
})

import { afterEach, describe, expect, it } from "bun:test"

import {
  startPricingScheduler,
  stopPricingScheduler,
} from "~/services/copilot/pricing-scheduler"

afterEach(() => {
  stopPricingScheduler()
})

describe("pricing scheduler", () => {
  it("refreshes pricing immediately on startup", async () => {
    let calls = 0

    await startPricingScheduler(() => {
      calls += 1
      return Promise.resolve({ status: "updated" })
    })

    expect(calls).toBe(1)
  })

  it("deduplicates concurrent scheduler starts", async () => {
    let calls = 0
    let resolveRefresh: ((value: { status: string }) => void) | undefined
    const updater = () => {
      calls += 1
      return new Promise<{ status: string }>((resolve) => {
        resolveRefresh = resolve
      })
    }

    const starts = [
      startPricingScheduler(updater),
      startPricingScheduler(updater),
    ]
    expect(calls).toBe(1)
    if (!resolveRefresh) throw new Error("Expected pending refresh")
    resolveRefresh({ status: "updated" })
    await Promise.all(starts)

    expect(calls).toBe(1)
  })

  it("does not reject startup when pricing refresh fails", async () => {
    let rejected = false
    try {
      await startPricingScheduler(() => Promise.reject(new Error("offline")))
    } catch {
      rejected = true
    }
    expect(rejected).toBe(false)
  })
})
